const config = $input.first().json;
const cities = [
  { city: '南京', latitude: 32.0603, longitude: 118.7969 },
  { city: '芜湖', latitude: 31.3525, longitude: 118.4331 },
];
return cities.map((city) => ({ json: { ...config, ...city } }));

const cities = $items('城市列表');
const responses = $input.all();
return responses.map((item, index) => ({
  json: {
    city: cities[index]?.json?.city || `城市 ${index + 1}`,
    latitude: cities[index]?.json?.latitude,
    longitude: cities[index]?.json?.longitude,
    recipientEmail: cities[index]?.json?.recipientEmail || '',
    fromEmail: cities[index]?.json?.fromEmail || '',
    useAi: Boolean(cities[index]?.json?.useAi),
    weather: item.json,
  },
}));

const weatherText = (code) => {
  if (code === 0) return '晴';
  if ([1, 2].includes(code)) return '晴间多云';
  if (code === 3) return '阴';
  if ([45, 48].includes(code)) return '雾';
  if ([51, 53, 55, 56, 57].includes(code)) return '毛毛雨';
  if ([61, 63, 65, 66, 67, 80, 81, 82].includes(code)) return '有雨';
  if ([71, 73, 75, 77, 85, 86].includes(code)) return '有雪';
  if ([95, 96, 99].includes(code)) return '雷雨';
  return '天气情况未知';
};
const round = (value) => Number.isFinite(Number(value)) ? Math.round(Number(value)) : null;
const items = $input.all();
const sections = [];
const cards = [];
const problems = [];
for (const item of items) {
  const { city, weather } = item.json;
  const daily = weather?.daily;
  const hourly = weather?.hourly;
  if (!daily?.time?.length || !hourly?.time?.length) {
    problems.push(city);
    sections.push(`【${city}】天气数据暂时不可用，请稍后查看。`);
    cards.push({ city, available: false });
    continue;
  }
  const date = daily.time[0];
  const max = round(daily.temperature_2m_max?.[0]);
  const min = round(daily.temperature_2m_min?.[0]);
  const apparentMax = round(daily.apparent_temperature_max?.[0]);
  const rainChance = round(daily.precipitation_probability_max?.[0]) ?? 0;
  const rain = Number(daily.precipitation_sum?.[0] ?? 0);
  const wind = round(daily.wind_speed_10m_max?.[0]) ?? 0;
  const gust = round(daily.wind_gusts_10m_max?.[0]) ?? 0;
  const uv = Number(daily.uv_index_max?.[0] ?? 0);
  const condition = weatherText(daily.weather_code?.[0]);
  const targetHours = ['09:00', '12:00', '15:00', '18:00', '21:00'];
  const hourlyRows = targetHours.map((clock) => {
    const index = hourly.time.indexOf(`${date}T${clock}`);
    if (index < 0) return `${clock} 暂无数据`;
    const temperature = round(hourly.temperature_2m?.[index]);
    const feels = round(hourly.apparent_temperature?.[index]);
    const probability = round(hourly.precipitation_probability?.[index]) ?? 0;
    return `${clock} ${weatherText(hourly.weather_code?.[index])} ${temperature}℃（体感 ${feels}℃），降水 ${probability}%`;
  });
  const advice = [];
  if (rainChance >= 50 || rain >= 1) advice.push('建议随身带伞，注意路面湿滑');
  if (max !== null && max >= 35) advice.push('注意防暑补水，减少午后户外活动');
  else if (max !== null && max >= 30) advice.push('午后偏热，注意补水防晒');
  if (min !== null && min <= 10) advice.push('早晚偏凉，建议增加衣物');
  if (gust >= 50 || wind >= 35) advice.push('风力较强，留意高空坠物并固定室外物品');
  if (uv >= 6) advice.push('紫外线较强，外出做好防晒');
  if (!advice.length) advice.push('天气整体平稳，按日常安排出行即可');
  sections.push([
    `【${city}】${condition}，${min}～${max}℃，最高体感 ${apparentMax}℃`,
    `降水概率 ${rainChance}%，预计降水 ${rain.toFixed(1)} mm；最大风速 ${wind} km/h，阵风 ${gust} km/h；UV ${uv.toFixed(1)}`,
    ...hourlyRows.map((row) => `- ${row}`),
    `建议：${advice.join('；')}。`,
  ].join('\n'));
  cards.push({ city, available: true, date, condition, min, max, apparentMax, rainChance, rain, wind, gust, uv, hourlyRows, advice });
}
const date = cards.find((card) => card.available)?.date || new Date().toLocaleDateString('zh-CN', { timeZone: 'Asia/Shanghai' });
const ruleSummary = `早上好，以下是 ${date} 南京与芜湖天气简报。\n\n${sections.join('\n\n')}\n\n数据来源：Open-Meteo。`;
const aiPrompt = `你是一名严谨、克制的中文天气编辑。请根据以下结构化天气内容，写一段适合晨间邮件开头的中文摘要。要求：1）不虚构数据；2）先说双城共同趋势，再指出差异；3）突出降雨、高温、大风等行动信息；4）80到140个汉字；5）只输出正文，不用标题。\n\n${ruleSummary}`;
return [{ json: { date, cards, problems, ruleSummary, aiPrompt, recipientEmail: items[0]?.json?.recipientEmail || '', fromEmail: items[0]?.json?.fromEmail || '', useAi: Boolean(items[0]?.json?.useAi) } }];

const base = $items('整理双城天气')[0].json;
const incoming = $input.first()?.json || {};
const aiText = typeof incoming.text === 'string' ? incoming.text.trim() : (typeof incoming.output === 'string' ? incoming.output.trim() : '');
const opening = aiText || '今日双城天气详情与出行建议如下，请结合降水、风力和体感温度合理安排出行。';
const escapeHtml = (value) => String(value).replace(/[&<>]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[character]);
const cardHtml = base.cards.map((card) => {
  if (!card.available) return `<section style="padding:16px;margin:12px 0;border:1px solid #f0c36d;border-radius:12px;background:#fff8e1"><h2 style="margin:0 0 8px">${escapeHtml(card.city)}</h2><p>天气数据暂时不可用，请稍后查看。</p></section>`;
  const hours = card.hourlyRows.map((row) => `<li style="margin:5px 0">${escapeHtml(row)}</li>`).join('');
  return `<section style="padding:18px;margin:14px 0;border:1px solid #dbe7f3;border-radius:12px;background:#f8fbff"><h2 style="margin:0 0 10px;color:#174a7c">${escapeHtml(card.city)} · ${escapeHtml(card.condition)}</h2><p style="font-size:20px;margin:8px 0"><strong>${card.min}～${card.max}℃</strong> <span style="font-size:14px;color:#52606d">最高体感 ${card.apparentMax}℃</span></p><p>降水概率 ${card.rainChance}% · 降水 ${card.rain.toFixed(1)} mm · 最大风速 ${card.wind} km/h · 阵风 ${card.gust} km/h · UV ${card.uv.toFixed(1)}</p><ul style="padding-left:22px">${hours}</ul><p style="margin-bottom:0;color:#8a4b08"><strong>建议：</strong>${escapeHtml(card.advice.join('；'))}。</p></section>`;
}).join('');
const warning = base.problems.length ? `<p style="padding:10px;background:#fff3cd;border-radius:8px">注意：${escapeHtml(base.problems.join('、'))}的数据本次获取失败。</p>` : '';
const html = `<div style="max-width:720px;margin:auto;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Microsoft YaHei',sans-serif;color:#243447;line-height:1.65"><h1 style="color:#0b5f8a">南京 · 芜湖每日天气简报</h1><p style="color:#52606d">${escapeHtml(base.date)} · 中国标准时间</p><p style="font-size:16px">${escapeHtml(opening)}</p>${warning}${cardHtml}<p style="margin-top:24px;font-size:12px;color:#7b8794">天气数据来自 Open-Meteo；预报存在不确定性，请以当地官方预警为准。${aiText ? '摘要由 AI 辅助生成。' : '本次使用规则版摘要。'}</p></div>`;
return [{ json: { toEmail: base.recipientEmail, fromEmail: base.fromEmail, subject: `南京·芜湖天气简报｜${base.date}`, html, usedAi: Boolean(aiText) } }];
